let idCounter=0;const uid=()=>`b${Date.now().toString(36)}${++idCounter}`;
function makeBlock(type,text='',i=0){const b={id:uid(),type,text,font:type==='body'?'Georgia':'Arial',size:type==='heading'?34:type==='body'?12:type==='eyebrow'?10:type==='terms'?9:14,color:type==='body'?'#9a6464':type==='terms'?'#a3aa9e':'#23342a',align:'left'};if(type==='image'){b.image=text;b.alt='';b.height=i===2?390:270;delete b.text}if(type==='cta'){b.url='#';b.color='#ffffff';b.size=14}if(type==='promo'){[b.text,b.body,b.cta]=text.split('|');b.url='https://offers.example/extras'}if(type==='footer'){b.size=11;b.color='#7d8872'}if(type==='unsubscribe'){b.url='#';b.size=11;b.color='#65765a'}return b}
function newMission(c,i){return {subject:c.initial.subject,preheader:c.initial.preheader,recipients:c.initial.recipients,blocks:c.initial.blocks.map(([t,x])=>makeBlock(t,x,i)),reflection:'',reviewed:false,score:0,review:null,edits:0}}
function newState(){return {version:2,name:'',difficulty:'standard',active:0,mission:0,view:'desktop',panel:'edit',started:false,seconds:0,missions:clients.map(newMission),complete:false}}
let state;try{state=JSON.parse(localStorage.getItem('inbox-rescue-direct-v2'));if(!state||state.version!==2||state.missions.length!==3)state=newState()}catch{state=newState()}
let selected=null,showOriginal=false,previewOnly=false,undoStacks=[[],[],[]],redoStacks=[[],[],[]],editSnapshot=null,activity=Date.now(),lastTick=Date.now(),toastTimeout;
function mission(){return state.missions[state.mission]}function client(){return clients[state.mission]}function selectedBlock(){return mission().blocks.find(b=>b.id===selected)}
function persist(){try{localStorage.setItem('inbox-rescue-direct-v2',JSON.stringify(state));$('#saveStatus').textContent='Saved on this device'}catch{$('#saveStatus').textContent='Storage full — download your work'}}
function score(){return Math.round(state.missions.reduce((n,m)=>n+m.score,0)/3)}function displayTime(){return `${String(Math.floor(state.seconds/60)).padStart(2,'0')}:${String(state.seconds%60).padStart(2,'0')}`}
function updateHeader(){$('#timer').innerHTML=`${displayTime()} <small>/ 30:00</small>`;$('#overall').innerHTML=`${score()}<span>/100</span>`}
function notify(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function checkpoint(){undoStacks[state.mission].push(JSON.stringify(mission()));if(undoStacks[state.mission].length>40)undoStacks[state.mission].shift();redoStacks[state.mission]=[]}
function changed(){const m=mission();m.reviewed=false;m.score=0;m.review=null;m.edits++;state.complete=false;state.started=true;activity=Date.now();persist();updateHeader();updateClientScores()}
function updateClientScores(){clients.forEach((c,i)=>{const el=$(`[data-score="${i}"]`);if(el)el.textContent=state.missions[i].reviewed?state.missions[i].score:'—'})}
function safeUrl(u){return /^(https?:\/\/|\/|#)/i.test(u??'')?u:'#'}
function safeImage(b){if(b.image==='upload'&&/^data:image\/(jpeg|png|webp);base64,/.test(b.upload??''))return b.upload;return images.find(x=>x.id===b.image)?.src||images[0].src}
function tools(b){return `<span class="block-name">${b.type==='body'?'Text':b.type}</span><div class="block-tools"><button class="drag" draggable="true" data-drag="${b.id}" aria-label="Drag block" title="Drag to reorder">⠿</button><button data-action="move" data-id="${b.id}" data-dir="-1" aria-label="Move block up" title="Move up">↑</button><button data-action="move" data-id="${b.id}" data-dir="1" aria-label="Move block down" title="Move down">↓</button><button data-action="delete" data-id="${b.id}" aria-label="Delete block" title="Remove this element">×</button></div>`}
function editable(id,prop,text,placeholder='Click to write',classes=''){return `<div class="${classes}" contenteditable="${previewOnly||showOriginal?'false':'plaintext-only'}" role="textbox" aria-label="Edit ${esc(prop)}" data-content="${id}" data-prop="${prop}" data-placeholder="${esc(placeholder)}" spellcheck="true">${esc(text)}</div>`}
function blockMarkup(b,c,interactive=true){const style=`font-family:${esc(b.font)};font-size:${Number(b.size)}px;color:${esc(b.color)};text-align:${esc(b.align)}`;let body='';if(['heading','body','eyebrow','terms'].includes(b.type))body=`<div class="text-block ${b.type==='eyebrow'?'eyebrowblock':b.type}" style="${style}">${editable(b.id,'text',b.text,b.type==='body'?'Write your email copy here':'Write '+b.type)}</div>`;if(b.type==='image')body=`<div class="image-block"><img src="${esc(safeImage(b))}" alt="${esc(b.alt)}" style="height:${Number(b.height)}px"><button class="image-action" data-action="images" data-id="${b.id}">↻ Replace photo / edit alt text</button></div>`;if(b.type==='cta')body=`<div class="cta-block" style="text-align:${esc(b.align)}"><div class="ctaeditable" style="${style};background:${c.color};color:white">${editable(b.id,'text',b.text,'Write a clear action')}</div></div>`;if(b.type==='promo')body=`<div class="promo-block"><h3>${editable(b.id,'text',b.text)}</h3><p>${editable(b.id,'body',b.body)}</p><div class="promo-cta">${editable(b.id,'cta',b.cta)}</div></div>`;if(b.type==='footer')body=`<div class="footer-block" style="${style}">${editable(b.id,'text',b.text,'Add sender name, postal address and permission statement')}</div>`;if(b.type==='unsubscribe')body=`<div class="unsubscribe-block" style="${style}">${editable(b.id,'text',b.text,'Unsubscribe / Manage preferences')}</div>`;if(b.type==='divider')body='<div class="divider-block"><hr></div>';return `<section class="block ${selected===b.id?'selected':''}" data-block="${b.id}" style="--brand:${c.color}">${interactive?tools(b):''}${body}</section>`}
function emailMarkup(m,c){return `<div class="envelope"><div class="inbox-chrome"><i class="dot"></i><i class="dot"></i><i class="dot"></i><span>CAMPAIGN DRAFT · NO EMAIL IS SENT</span></div><div class="mail-fields"><div class="mail-field"><label>From</label><div style="padding:5px 0">${c.name} &lt;offers@${c.id}.example&gt;</div></div>${[['recipients','To'],['subject','Subject'],['preheader','Preview']].map(([k,label])=>`<div class="mail-field"><label>${label}</label>${editable('meta',k,m[k],'Click to edit '+label,k==='subject'?'subject':'')}</div>`).join('')}</div><div class="email-inner"><div class="email-topline">Your next great moment starts here &nbsp; · &nbsp; View in browser</div><div class="brand-header" style="--brand:${c.color}"><div class="brand-name ${c.id}">${c.name}</div><div class="brand-tag">${c.tag}</div></div><div class="mail-nav">${c.nav}</div><div id="emailBlocks">${m.blocks.length?m.blocks.map(b=>blockMarkup(b,c,!showOriginal&&!previewOnly)).join(''):'<div class="empty-canvas">Your email is empty. Add a heading, image, copy and call to action below.</div>'}</div></div></div>`}
function original(){return newMission(client(),state.mission)}
function leftPanel(){const c=client();return `<aside class="left"><div class="left-heading eyebrow muted">YOUR CAMPAIGNS</div><nav class="clientlist" aria-label="Choose campaign">${clients.map((c,i)=>`<button class="client ${state.mission===i?'active':''}" data-action="client" data-index="${i}"><span class="client-symbol" style="background:${c.color}">${c.symbol}</span><span>${c.name}<small>0${i+1} · ${i===0?'Travel':i===1?'Telecom':'Retail'}</small></span><b data-score="${i}">${state.missions[i].reviewed?state.missions[i].score:'—'}</b></button>`).join('')}</nav><div><div class="step-number">0${state.mission+1} / CLIENT BRIEF</div><h2 class="brief-title">${c.title}</h2><p class="brief-copy">${c.brief}</p><button class="ghost mobile-only" data-action="brief">Show offer details ↓</button></div><div class="brief-details"><div class="brief-label">The actual offer</div><p class="brief-value">${c.offer}</p><div class="brief-label">Who should receive it?</div><p class="brief-value">${c.audience}</p><div class="brief-label">One campaign goal</div><p class="brief-value">${c.goal}</p><div class="brief-label">Landing page</div><p class="brief-value" style="overflow-wrap:anywhere">${c.destination}</p><p class="lesson">Use these facts to correct the email. Offers and .example links are fictional classroom material.</p></div><div class="brief-box settings"><div><label class="fieldlabel" for="studentName">Your name</label><input id="studentName" maxlength="60" placeholder="Student name" value="${esc(state.name)}"></div><div><label class="fieldlabel" for="difficulty">Difficulty</label><select id="difficulty"><option value="guided" ${state.difficulty==='guided'?'selected':''}>Guided · hints</option><option value="standard" ${state.difficulty==='standard'?'selected':''}>Standard</option><option value="expert" ${state.difficulty==='expert'?'selected':''}>Expert · no hints</option></select></div></div><div class="timeplan"><b>30–40 minute studio</b><br>2 min: inspect each email<br>6 min: edit each email<br>2 min: review + explain each<br><br>Score at least 90 on <b>every</b> campaign and work for 30 active minutes to finish.</div><button class="ghost helpbtn" data-action="help">How the editor works ↗</button><p class="lesson">Session 2 · Week 12<br>Copy & tone: slide 3<br>Design & type: slides 6–10<br>CTAs: slides 11–12<br>Images: slides 13–15<br>Permissions: slides 20–26</p></aside>`}
function canvas(){return `<section class="workspace"><div class="workspace-head"><div><h1>Edit the email. Directly.</h1><p>Click any text to rewrite it. Select a block to style, move or remove it.</p></div><div class="viewbuttons"><button data-action="view" data-view="desktop" class="${state.view==='desktop'?'active':''}" aria-label="Desktop view">▣</button><button data-action="view" data-view="mobile" class="${state.view==='mobile'?'active':''}" aria-label="Mobile view">▯</button><button data-action="preview" class="${previewOnly?'active':''}">${previewOnly?'Edit':'Preview'}</button></div></div>${showOriginal?'<div class="readonly-banner">Original email · read only. <button class="ghost" data-action="original">Return to your edit →</button></div>':state.difficulty==='guided'?'<div class="hintstrip"><b>EDITOR TIP</b><span>Match the subject to the real offer. Fix the copy, CTA, image and permissions. Remove competing promotions. Add missing footer elements.</span></div>':'<div class="hintstrip"><span class="editing-badge">LIVE EMAIL EDITOR</span><span>Rewrite · replace · remove · add · reorder</span></div>'}<div class="email-wrap ${state.view==='mobile'?'mobile':''} ${previewOnly||showOriginal?'no-preview':''}" id="emailCanvas">${emailMarkup(showOriginal?original():mission(),client())}</div>${!showOriginal&&!previewOnly?'<div class="add-zone"><button data-action="add">＋ Add email element</button><button data-action="original">Compare original</button></div>':''}<p class="canvas-bottom">Fictional classroom campaign · Unsplash photography · No message is sent<br>Drag using ⠿, or use the ↑ ↓ controls. All changes save on this device.</p></section>`}
function emptyInspector(){return `<span class="eyebrow muted">ON-CANVAS EDITING</span><h2 class="paneltitle">Start with the email.</h2><p class="panelcopy">This is your working draft. You can edit every part of its message directly.</p><div class="selection-empty"><svg width="35" height="38" viewBox="0 0 35 38" fill="none" aria-hidden="true"><path d="M8 3L28 21L18 22L14 32L8 3Z" stroke="#77925c" stroke-width="1.5"/></svg><div class="panelcopy">Click text to rewrite.<br>Click a photo to replace.<br>Select a block for its settings.</div></div><div class="dimension">↗ Text is edited inside the email.<br>＋ Add a missing element below it.<br>× Remove an unnecessary block.<br>↑ ↓ Rearrange the layout.</div><div class="inspector-section"><button class="primary lime" data-action="add">＋ Add email element</button></div>${state.difficulty==='guided'?'<div class="tip"><b>Look carefully</b><br>A polished design can still have a misleading subject, the wrong audience, competing goals or missing opt-out information.</div>':''}`}
function styleInspector(b){return `<span class="eyebrow muted">SELECTED ELEMENT</span><h2 class="paneltitle">${b.type==='body'?'Email copy':b.type.charAt(0).toUpperCase()+b.type.slice(1)}</h2><p class="panelcopy">Edit its words directly in the email. Use these settings for presentation.</p>${b.type==='image'?imageInspector(b):b.type==='divider'?'<p class="panelcopy">A quiet divider can give the reader a little breathing room.</p>':`<label class="fieldlabel" for="font">Font family</label><select id="font" data-style="font">${['Arial','Helvetica','Georgia','Verdana','Times New Roman','Courier New'].map(f=>`<option ${b.font===f?'selected':''}>${f}</option>`).join('')}</select><div class="controlsrow"><div><label class="fieldlabel" for="size">Size (px)</label><input id="size" data-style="size" type="number" min="9" max="64" value="${b.size}"></div><div><label class="fieldlabel" for="color">Text colour</label><input id="color" data-style="color" type="color" value="${b.color}" ${b.type==='cta'?'disabled':''}></div></div><label class="fieldlabel">Alignment</label><div class="controlbtns">${['left','center','right'].map(a=>`<button data-action="align" data-value="${a}" class="${b.align===a?'on':''}">${a[0].toUpperCase()+a.slice(1)}</button>`).join('')}</div>${['cta','unsubscribe','promo'].includes(b.type)?`<label class="fieldlabel" for="linkurl">Destination URL</label><input id="linkurl" data-style="url" type="text" value="${esc(b.url||'')}" placeholder="https://brand.example/page"><p class="image-note">Demo link only. Buttons remain editable and will not send or submit anything.</p>`:''}`}<div class="inspector-section"><label class="fieldlabel">Position & structure</label><div class="controlbtns"><button data-action="move" data-id="${b.id}" data-dir="-1">↑ Move up</button><button data-action="move" data-id="${b.id}" data-dir="1">↓ Move down</button></div><div class="footer-actions"><button class="secondary" data-action="duplicate" data-id="${b.id}">Duplicate</button><button class="secondary danger" data-action="delete" data-id="${b.id}">Remove element</button></div></div>${b.type!=='image'?'<div class="inspector-section"><button class="secondary small" style="width:100%" data-action="readable">Apply readable style to all text</button><p class="image-note">Consistent fonts, legible sizes and darker text throughout this email.</p></div>':''}`}
function imageInspector(b){return `<p class="panelcopy">Choose a photo for this campaign, or use your own.</p><div class="image-library">${images.map(im=>`<button class="image-choice ${b.image===im.id?'chosen':''}" data-action="replaceimage" data-value="${im.id}"><img src="${im.src}" alt="${im.alt}"><span>${im.name}</span></button>`).join('')}</div><label class="fieldlabel" for="imageAlt">Alt text</label><textarea id="imageAlt" data-style="alt" placeholder="Describe what the image shows for someone who cannot see it.">${esc(b.alt)}</textarea><label class="fieldlabel" for="imageHeight">Image height (px)</label><input id="imageHeight" data-style="height" type="number" min="100" max="500" value="${b.height}"><p class="image-note">Support the message with the photo. Keep the offer, deadline and CTA as live text.</p><label class="upload-label">＋ Upload a photo<input type="file" id="photoUpload" accept="image/jpeg,image/png,image/webp"></label><p class="image-note">JPG, PNG or WebP · up to 1.5 MB. Stored only on this device.</p>`}
function allCopy(m){return m.blocks.filter(b=>['body','heading','terms','eyebrow'].includes(b.type)).map(b=>b.text||'').join(' ')}
function wordCount(t){return String(t||'').trim().split(/\s+/).filter(Boolean).length}
function validLink(u,expected){try{const a=new URL(u);const b=new URL(expected);return a.protocol==='https:'&&a.hostname===b.hostname&&a.pathname.replace(/\/$/,'')===b.pathname.replace(/\/$/,'')}catch{return false}}
function readableColor(color){if(!/^#[0-9a-f]{6}$/i.test(color||''))return false;const rgb=[1,3,5].map(n=>parseInt(color.slice(n,n+2),16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return 1.05/(.2126*rgb[0]+.7152*rgb[1]+.0722*rgb[2]+.05)>=4.5}
function evaluate(m,c){const p=c.patterns,copy=allCopy(m),body=m.blocks.filter(b=>b.type==='body').map(b=>b.text).join(' '),terms=m.blocks.filter(b=>b.type==='terms').map(b=>b.text).join(' '),ctas=m.blocks.filter(b=>b.type==='cta'),imagesIn=m.blocks.filter(b=>b.type==='image'),footer=m.blocks.filter(b=>b.type==='footer').map(b=>b.text).join(' '),unsubscribe=m.blocks.filter(b=>b.type==='unsubscribe'),texts=m.blocks.filter(b=>['heading','body','eyebrow','terms'].includes(b.type));const factual=copy+' '+m.subject+' '+m.preheader;
return [
 {key:'subject',weight:10,title:'A truthful subject & preview',ok:p.topic.test(m.subject)&&p.value.test(m.subject)&&!p.wrong.test(m.subject+' '+m.preheader)&&m.subject.length>=12&&m.subject.length<=90&&m.preheader.trim().length>=20,hint:'Rewrite the subject with the real offer or price. Add a relevant preview; remove unsupported promises.',slide:'3'},
 {key:'audience',weight:10,title:'The relevant, opted-in audience',ok:/opted[ -]?in|explicit\s*consent|consented|subscribed/i.test(m.recipients)&&/uae|united arab emirates/i.test(m.recipients)&&p.audience.test(m.recipients)&&!/unsubscribed|purchased|everyone|all\s*(past|uae)|social\s*media/i.test(m.recipients),hint:'Edit the To line to describe the relevant opted-in UAE audience in the brief. Exclude purchased lists and unsubscribed people.',slide:'3, 20–26'},
 {key:'copy',weight:15,title:'Accurate, relevant live copy',ok:wordCount(body)>=35&&p.copy.test(body)&&p.value.test(body)&&!p.wrong.test(factual),hint:'Rewrite the body in at least 35 words using the actual offer. Remove false discounts, unsupported claims and unsafe requests.',slide:'3'},
 {key:'focus',weight:10,title:'One clear campaign goal',ok:ctas.length===1&&m.blocks.filter(b=>b.type==='promo').length===0&&!p.unrelated.test(copy),hint:'Remove the competing promotion and its extra CTA. Keep the email focused on this brief’s single goal.',slide:'3, 12'},
 {key:'cta',weight:10,title:'A specific action & destination',ok:ctas.length===1&&p.cta.test(ctas[0].text.trim())&&validLink(ctas[0].url,c.destination),hint:'Rewrite the button using an action appropriate to the goal, then set its Destination URL to the landing page in the brief.',slide:'11–12'},
 {key:'deadline',weight:10,title:'Real urgency & clear conditions',ok:p.deadline.test(terms)&&p.conditions.every(re=>re.test(copy))&&wordCount(terms)>=12&&!/10\s*minutes|ends\s*soon|whenever|guaranteed|no\s*conditions|all\s*month/i.test(terms),hint:'Edit or add offer terms with the exact deadline and all important conditions in the client brief.',slide:'3, 12'},
 {key:'type',weight:10,title:'Consistent, legible typography',ok:texts.length>=3&&new Set(texts.map(b=>b.font)).size<=2&&texts.every(b=>b.size>=(b.type==='heading'?26:b.type==='body'?14:b.type==='terms'?12:10)&&readableColor(b.color))&&m.blocks.some(b=>b.type==='heading')&&m.blocks.some(b=>b.type==='body'),hint:'Use readable sizes, sufficient contrast and no more than two consistent fonts. You can style each block or apply a readable style to all text.',slide:'6–10'},
 {key:'image',weight:5,title:'Relevant image, size & alt text',ok:imagesIn.length===1&&(imagesIn[0].image===c.id||imagesIn[0].image==='upload')&&wordCount(imagesIn[0].alt)>=5&&imagesIn[0].height>=120&&imagesIn[0].height<=240,hint:'Select a relevant photo, add descriptive alt text (at least 5 words), and size it to 120–240 px high.',slide:'13–15'},
 {key:'structure',weight:5,title:'A usable email structure',ok:m.blocks.some(b=>b.type==='heading')&&m.blocks.some(b=>b.type==='body'&&wordCount(b.text)>=35)&&m.blocks.some(b=>b.type==='terms')&&ctas.length===1&&m.blocks.findIndex(b=>b.type==='heading')<m.blocks.findIndex(b=>b.type==='cta')&&m.blocks.findIndex(b=>b.type==='body')<m.blocks.findIndex(b=>b.type==='cta'),hint:'Keep a headline and useful live-text copy before the primary action, with visible offer conditions.',slide:'6–8, 13–15'},
 {key:'sender',weight:5,title:'Sender identity & postal address',ok:footer.toLowerCase().includes(c.name.toLowerCase())&&/\d+/.test(footer)&&/street|avenue|road|p\.?\s*o\.?\s*box|training\s*address/i.test(footer)&&/dubai|uae|united arab emirates/i.test(footer),hint:'Edit or add a footer with the brand’s identity and a clearly labelled fictional training postal address.',slide:'5, 21, 23'},
 {key:'optout',weight:5,title:'An easy opt-out',ok:unsubscribe.some(b=>/unsubscribe|opt[ -]?out/i.test(b.text)&&/^https:\/\/[^\s]+/i.test(b.url))&&!/cannot\s*unsubscribe|no\s*opt[ -]?out/i.test(footer),hint:'Add an Unsubscribe element. Give it a clear label and a demo https:// destination in its settings.',slide:'5, 21–26'},
 {key:'reasoning',weight:5,title:'Explain the marketing decisions',ok:wordCount(m.reflection)>=40,hint:'In the Review panel, explain your audience, goal, CTA and at least two edits in 40 or more words.',slide:'16–17'}];}
function reviewPanel(){const m=mission();let html=`<span class="eyebrow muted">CAMPAIGN REVIEW</span><h2 class="paneltitle">${client().name} · ready to send?</h2><p class="panelcopy">Check the email against the brief. Aim for at least 90/100 on this campaign.</p>`;if(m.reviewed){const rows=m.review||evaluate(m,client());html+=`<div class="review-pop"><div class="scorebig">${m.score}<small>/100</small></div><div class="progress"><div style="width:${m.score}%"></div></div><p class="panelcopy">${m.score>=90?'This campaign meets the launch score.':'Keep editing. Review your email again after your changes.'}</p>${state.difficulty==='expert'?`<p class="tip">${rows.filter(r=>r.ok).length} of ${rows.length} studio checks passed. Expert mode does not identify the failed elements.</p>`:`<ul class="review-items">${rows.map(r=>`<li class="${r.ok?'passed':'failed'}"><span class="checkmark">${r.ok?'✓':'○'}</span><div><div class="score-label"><b>${r.title}</b><span>${r.ok?r.weight:0}/${r.weight}</span></div>${!r.ok?`<small>${r.hint}</small>`:''}<small>Slides ${r.slide}</small></div></li>`).join('')}</ul>`}</div>`}else html+=`<div class="tip">${state.difficulty==='guided'?'Review checklist: accurate subject, opted-in audience, relevant copy, one CTA, genuine deadline, readable type, relevant image + alt text, sender identity and opt-out.':'Your edits have not been reviewed yet. Submit this email when you are ready.'}</div>`;return html+`<div class="reflection"><label class="fieldlabel" for="reflection">Your marketing decisions</label><p class="panelcopy">Explain who this is for, the one goal, your CTA and two important edits you made.</p><textarea id="reflection" placeholder="Explain your decisions in at least 40 words…">${esc(m.reflection)}</textarea><p class="counter" id="wordCounter">${wordCount(m.reflection)} words / 40 minimum</p><button class="primary lime" data-action="review" style="width:100%">Review this email ↗</button></div><p class="lesson">Automated checks use the specific offer facts and structural rules. They cannot judge writing quality or verify that an uploaded photo is relevant. Your teacher reviews meaning, originality and accuracy.</p>`}
function panel(){return `<div class="paneltabs"><button data-action="panel" data-panel="edit" class="${state.panel==='edit'?'active':''}">Element settings</button><button data-action="panel" data-panel="review" class="${state.panel==='review'?'active':''}">Review & explain</button></div><div id="inspectorBody">${state.panel==='review'?reviewPanel():selectedBlock()?styleInspector(selectedBlock()):emptyInspector()}</div><div class="footer-actions"><button class="ghost" data-action="undo" ${undoStacks[state.mission].length?'':'disabled'}>↶ Undo</button><button class="ghost" data-action="redo" ${redoStacks[state.mission].length?'':'disabled'}>↷ Redo</button><button class="ghost" data-action="download">Export emails ↓</button></div>`}
function render(){updateHeader();$('#app').innerHTML=`<div class="shell">${leftPanel()}${canvas()}<aside class="right" id="rightPanel">${panel()}</aside></div>`;persist()}
function renderPanel(){const el=$('#rightPanel');if(el)el.innerHTML=panel()}
function renderCanvas(){const w=$('.workspace');if(w)w.outerHTML=canvas()}
function selectBlock(id,scroll=false){selected=id;state.panel='edit';$$('.block.selected').forEach(b=>b.classList.remove('selected'));const el=$(`[data-block="${id}"]`);if(el)el.classList.add('selected');renderPanel();if(scroll&&window.innerWidth<641)$('#rightPanel').scrollIntoView({behavior:'smooth',block:'start'})}
function openModal(html){$('#modal').innerHTML=`<section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialogTitle"><button class="close" data-action="close" aria-label="Close dialog">×</button>${html}</section>`;$('#modal').hidden=false;$('#modal .close').focus()}
function closeModal(){$('#modal').hidden=true;$('#modal').innerHTML=''}
function addModal(){openModal(`<span class="eyebrow muted">BUILD THE EMAIL</span><h2 id="dialogTitle">Add an element.</h2><p>The new element appears after your selected block. Click its text in the email to write.</p><div class="block-library">${[['heading','H','Heading','A clear benefit or message'],['body','¶','Email copy','Write the offer in your own words'],['image','▧','Image','Add a relevant photograph'],['cta','↗','Call to action','One specific next step'],['terms','※','Offer terms','Deadline and conditions'],['footer','≡','Sender footer','Identity and postal address'],['unsubscribe','↩','Unsubscribe','A clear way to opt out'],['divider','—','Divider','Give the layout some space'],['eyebrow','Aa','Small heading','Add context above the headline']].map(([type,icon,label,desc])=>`<button class="library-item" data-action="insert" data-type="${type}"><b>${icon}</b>${label}<small>${desc}</small></button>`).join('')}</div>`)}
function insertBlock(type){checkpoint();const defaults={heading:'Your campaign headline',body:'Write your email copy here. Explain the relevant offer clearly, with one goal and a useful next step for your audience.',image:client().id,cta:'Your call to action',terms:'Add the true deadline, offer details and important conditions.',footer:`${client().name}\nTraining address: Office 12, Example Avenue, Dubai, UAE\nYou received this because you opted in to relevant offers.`,unsubscribe:'Unsubscribe · Manage preferences',eyebrow:'YOUR NEXT GREAT MOMENT',divider:''};const b=makeBlock(type,defaults[type]||'');if(type==='unsubscribe')b.url=`https://${client().id}.example/unsubscribe`;if(type==='image'){b.height=200;b.alt=''}if(type==='body'){b.font='Arial';b.size=16;b.color='#253b2d'}if(type==='terms'){b.font='Arial';b.size=12;b.color='#58674e'}const index=mission().blocks.findIndex(x=>x.id===selected);mission().blocks.splice(index<0?mission().blocks.length:index+1,0,b);selected=b.id;changed();closeModal();renderCanvas();renderPanel();const el=$(`[data-block="${b.id}"]`);if(el){el.classList.add('inserted');el.scrollIntoView({behavior:'smooth',block:'center'})}notify('Element added. Click it to write your content.')}
function moveBlock(id,dir){const m=mission(),i=m.blocks.findIndex(b=>b.id===id),j=i+dir;if(i<0||j<0||j>=m.blocks.length)return;checkpoint();[m.blocks[i],m.blocks[j]]=[m.blocks[j],m.blocks[i]];selected=id;changed();renderCanvas();renderPanel()}
function removeBlock(id){if(!mission().blocks.some(b=>b.id===id))return;checkpoint();const mi=state.mission;const el=$(`[data-block="${id}"]`);if(el)el.classList.add('removing');setTimeout(()=>{const m=state.missions[mi];m.blocks=m.blocks.filter(b=>b.id!==id);m.reviewed=false;m.score=0;m.review=null;m.edits++;state.complete=false;if(selected===id)selected=null;if(state.mission===mi){changed();renderCanvas();renderPanel()}else{persist();updateHeader();updateClientScores()}notify('Element removed. Use Undo to restore it.')},160)}
function updateBlockVisual(b){const el=$(`[data-block="${b.id}"]`);if(!el)return;el.outerHTML=blockMarkup(b,client())}
function review(){const m=mission();const rows=evaluate(m,client());m.score=rows.filter(r=>r.ok).reduce((n,r)=>n+r.weight,0);m.review=rows;m.reviewed=true;state.panel='review';persist();updateHeader();updateClientScores();renderPanel();notify(m.score>=90?'Campaign passed. Continue to the next client.':'Review complete. Keep editing the email itself.');if(window.innerWidth<641)$('#rightPanel').scrollIntoView({behavior:'smooth',block:'start'})}
function canFinish(){return state.seconds>=1800&&state.missions.every(m=>m.reviewed&&m.score>=90)}
function gateText(){const remaining=state.missions.filter(m=>!m.reviewed||m.score<90).length;return `${remaining?`${remaining} campaign${remaining===1?' still needs':'s still need'} a reviewed score of at least 90. `:''}${state.seconds<1800?`${Math.ceil((1800-state.seconds)/60)} more active minute(s) required. Refine your wording, test the mobile layout and prepare your explanation.`:''}`||'All three emails meet the launch score and your 30-minute studio time is complete.'}
function launchModal(completed=false){openModal(`<span class="eyebrow muted">${completed?'STUDIO COMPLETE':'YOUR CAMPAIGN PORTFOLIO'}</span><h2 id="dialogTitle">${completed?'Three emails.<br>Ready for the inbox.':'Before you send,<br>check every detail.'}</h2><p>${completed?`${esc(state.name||'Marketer')}, you completed the email editing challenge.`:'Your work is the three emails you have edited, with your own copy, imagery, layout and explanations.'}</p><div class="report-scores">${clients.map((c,i)=>`<div class="report-card"><small>${c.name}</small><b>${state.missions[i].score}<small>/100</small></b><small>${state.missions[i].reviewed?state.missions[i].score>=90?'Passed':'Keep editing':'Not reviewed'}</small><button class="ghost" data-action="openclient" data-index="${i}">Open email →</button></div>`).join('')}</div><div class="launch-note" id="gateText">${gateText()}</div><p class="subtle">Active studio time: <span id="launchTime">${displayTime()}</span> · Average score ${score()}/100 · ${state.difficulty} mode. The timer pauses while the tab is hidden or after 90 seconds without activity.</p><div class="actions">${!completed?`<button class="primary lime" id="finishButton" data-action="finish" ${canFinish()?'':'disabled'}>Complete the challenge ✓</button>`:''}<button class="secondary" data-action="download">Download my three emails ↓</button></div><p class="subtle">Fictional teaching examples based on Session 2 Week 12. No marketing email is sent. Automated marks assess stated offer facts and structure; teacher review assesses the quality of your decisions.</p>${completed?'<button class="ghost" data-action="restart">Start a fresh attempt</button>':''}`);if(completed)for(let i=0;i<32;i++){const el=document.createElement('i');el.className='confetti';el.style.left=(Math.random()*95)+'%';el.style.background=['#99b74f','#d7be6f','#407e6b','#dbe5ba'][i%4];el.style.animationDelay=(Math.random()*.6)+'s';$('#modal .dialog').appendChild(el)}}
function helpModal(){openModal(`<span class="eyebrow muted">YOUR WORKING EMAIL STUDIO</span><h2 id="dialogTitle">The email is<br>your canvas.</h2><p><b>1.</b> Read the real offer in the client brief. The email contains deliberate mistakes.</p><p><b>2.</b> Click the subject, preview, To line, headline, copy or button label and type your correction directly.</p><p><b>3.</b> Click a photo to replace it and add alt text. Select any block for font, size, colour, alignment or link settings.</p><p><b>4.</b> Use × to remove a block, ↑ ↓ or the drag handle to move it, and <b>＋ Add email element</b> below the draft to insert missing content.</p><p><b>5.</b> Open <b>Review & explain</b>, write your reasoning and review your email. Repeat for all three clients.</p><div class="launch-note">Work for at least 30 active minutes and score 90+ on every campaign. Your revised emails can be downloaded as a portfolio.</div><div class="actions"><button class="primary" data-action="close">Start editing →</button></div>`)}
async function imageData(src){if(src.startsWith('data:'))return src;const response=await fetch(src);if(!response.ok)throw Error('Image download failed');const blob=await response.blob();return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob)})}
async function download(){notify('Preparing your three edited emails…');try{const mcopy=JSON.parse(JSON.stringify(state.missions));const refs=[...new Set(mcopy.flatMap(m=>m.blocks.filter(b=>b.type==='image').map(safeImage)))];const data=await Promise.all(refs.map(async s=>[s,await imageData(s)]));const map=new Map(data);let oldPreview=previewOnly,oldOriginal=showOriginal;previewOnly=true;showOriginal=false;let sections;try{sections=clients.map((c,i)=>{let mail=emailMarkup(mcopy[i],c);for(const [src,url] of map)mail=mail.split(esc(src)).join(url);return `<section class="campaign"><h2>${c.name} · ${mcopy[i].reviewed?mcopy[i].score+'/100':'Not reviewed'}</h2><p class="brief"><b>Client brief:</b> ${esc(c.offer)}<br><b>Audience:</b> ${esc(c.audience)}<br><b>Goal:</b> ${esc(c.goal)}</p>${mail}<h3>My marketing decisions</h3><p class="reason">${esc(mcopy[i].reflection)}</p><h3>Review checks</h3><ul>${evaluate(mcopy[i],c).map(r=>`<li>${r.ok?'✓':'Needs revision:'} ${r.title} (${r.ok?r.weight:0}/${r.weight})</li>`).join('')}</ul></section>`}).join('')}finally{previewOnly=oldPreview;showOriginal=oldOriginal}
const html=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(state.name||'Student')} · Email Marketing Portfolio</title><style>body{font:14px Arial,sans-serif;color:#243c2c;max-width:760px;margin:35px auto;padding:20px}h1{font-size:32px}h2{margin-top:45px}p{line-height:1.8}.brief{font-size:12px;padding:18px;background:#f1f4ec}.envelope{border:1px solid #ddd;background:white;max-width:680px;margin:auto}.inbox-chrome{display:none}.mail-fields{padding:20px;border-bottom:1px solid #ddd}.mail-field{display:grid;grid-template-columns:65px 1fr;gap:8px;padding:5px 0;font-size:12px}.mail-field label{color:#88927e}.email-topline{text-align:center;padding:14px;font-size:10px;background:#f4f5f1}.brand-header{padding:28px;background:var(--brand);color:white;display:flex;justify-content:space-between;align-items:center}.brand-name{font:bold 32px Georgia}.brand-tag{font-size:9px;letter-spacing:1px}.mail-nav{text-align:center;padding:15px;font-size:10px;color:#718068}.text-block{padding:16px 30px;line-height:1.7;overflow-wrap:anywhere}.heading{line-height:1.2;font-weight:bold}.eyebrowblock{letter-spacing:2px}.image-block img{width:100%;object-fit:cover;display:block}.cta-block{padding:12px 30px 22px}.ctaeditable{padding:14px 25px;display:inline-block;border-radius:3px;font-weight:bold}.promo-block{margin:20px;padding:20px;background:#f0f0ec}.promo-block p{font-size:12px}.footer-block{padding:20px 30px;background:#f1f3ec;line-height:1.8}.unsubscribe-block{padding:10px 30px 20px;background:#f1f3ec;text-decoration:underline}.divider-block{padding:10px 30px}.block-tools,.block-name,.image-action{display:none}.block [contenteditable]{white-space:pre-wrap}.reason{white-space:pre-wrap}.campaign{page-break-before:always}li{line-height:1.9;font-size:12px}.note{font-size:11px;color:#748366}@media print{body{max-width:none}.campaign{page-break-before:always}}</style></head><body><h1>Email Marketing · Campaign Portfolio</h1><p>Student: ${esc(state.name||'Unnamed')}<br>Difficulty: ${state.difficulty}<br>Active studio time: ${displayTime()}<br>Average reviewed score: ${score()}/100<br>Status: ${state.complete?'Completed':'Work in progress'}</p><p class="note">Three emails edited directly from faulty drafts. Classroom simulations based on Session 2 Week 12. Photos: Unsplash or student upload. Fictional offers, sender addresses and demo links; no email is sent.</p>${sections}<p class="note">Automatic checks assess stated offer facts and structure, not writing quality. Uploaded image relevance and the quality of the student’s explanation require teacher review.</p></body></html>`;
const blob=new Blob([html],{type:'text/html;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='my-three-email-campaigns.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);notify('Portfolio downloaded — all three edited emails, with photos.')}catch{notify('Could not prepare the portfolio. Please try again.')}}
function openClient(i){state.mission=Number(i);selected=null;showOriginal=false;previewOnly=false;state.panel='edit';render();window.scrollTo({top:0,behavior:'smooth'})}
function applyReadable(){checkpoint();mission().blocks.forEach(b=>{if(['heading','body','eyebrow','terms','footer'].includes(b.type)){b.font='Arial';b.size=b.type==='heading'?34:b.type==='body'?16:b.type==='terms'?12:b.type==='footer'?11:11;b.color=b.type==='footer'?'#5d6c52':'#253b2d'}});changed();renderCanvas();renderPanel();notify('Readable sizes, consistent fonts and darker text applied.')}
function undo(redo=false){const source=redo?redoStacks:undoStacks,target=redo?undoStacks:redoStacks;if(!source[state.mission].length)return;target[state.mission].push(JSON.stringify(mission()));state.missions[state.mission]=JSON.parse(source[state.mission].pop());selected=null;state.complete=false;persist();render();notify(redo?'Change restored.':'Previous edit restored.')}
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button){const block=e.target.closest('[data-block]');if(block&&!previewOnly&&!showOriginal)selectBlock(block.dataset.block);return}const a=button.dataset.action,id=button.dataset.id;if((previewOnly||showOriginal)&&['delete','move','duplicate','replaceimage','images'].includes(a))return;
if(a==='client')openClient(button.dataset.index);
else if(a==='openclient'){closeModal();openClient(button.dataset.index)}
else if(a==='view'){state.view=button.dataset.view;renderCanvas();persist()}
else if(a==='preview'){previewOnly=!previewOnly;selected=null;renderCanvas();renderPanel()}
else if(a==='original'){showOriginal=!showOriginal;selected=null;renderCanvas();renderPanel()}
else if(a==='panel'){state.panel=button.dataset.panel;renderPanel()}
else if(a==='images'){selectBlock(id,true)}
else if(a==='add')addModal();
else if(a==='insert')insertBlock(button.dataset.type);
else if(a==='delete')removeBlock(id);
else if(a==='move')moveBlock(id,Number(button.dataset.dir));
else if(a==='duplicate'){const b=mission().blocks.find(x=>x.id===id);if(!b)return;checkpoint();const clone={...b,id:uid()};mission().blocks.splice(mission().blocks.indexOf(b)+1,0,clone);selected=clone.id;changed();renderCanvas();renderPanel();notify('Element duplicated.')}
else if(a==='replaceimage'){const b=selectedBlock();if(!b)return;checkpoint();b.image=button.dataset.value;delete b.upload;changed();updateBlockVisual(b);renderPanel();notify('Photo replaced. Write descriptive alt text in the settings.')}
else if(a==='align'){const b=selectedBlock();if(!b)return;checkpoint();b.align=button.dataset.value;changed();updateBlockVisual(b);renderPanel()}
else if(a==='readable')applyReadable();
else if(a==='review')review();
else if(a==='launch')launchModal();
else if(a==='finish'){if(canFinish()){state.complete=true;persist();launchModal(true)}}
else if(a==='help')helpModal();
else if(a==='close')closeModal();
else if(a==='download')download();
else if(a==='undo')undo();
else if(a==='redo')undo(true);
else if(a==='brief')$('.left').classList.toggle('expanded');
else if(a==='restart'){if(confirm('Start a fresh attempt? Download your edited emails first if you want to keep them.')){state=newState();selected=null;showOriginal=false;previewOnly=false;undoStacks=[[],[],[]];redoStacks=[[],[],[]];closeModal();render()}}
});
document.addEventListener('focusin',e=>{if(e.target.matches('[data-content],#reflection'))checkpoint()});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.content){if(previewOnly||showOriginal)return;const value=el.innerText??el.textContent;if(el.dataset.content==='meta')mission()[el.dataset.prop]=value;else{const b=mission().blocks.find(b=>b.id===el.dataset.content);if(b)b[el.dataset.prop]=value}changed();if(state.panel==='review')renderPanel()}
if(el.id==='reflection'){mission().reflection=el.value;changed();$('#wordCounter').textContent=`${wordCount(el.value)} words / 40 minimum`;const previous=$('.review-pop');if(previous)previous.innerHTML='<p class="tip">Your explanation changed. Review this email again for an updated score.</p>'}
if(el.id==='studentName'){state.name=el.value;persist()}});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='difficulty'){state.difficulty=el.value;renderCanvas();renderPanel();persist()}
if(el.dataset.style){const b=selectedBlock();if(!b)return;checkpoint();const k=el.dataset.style;let v=el.value;if(k==='size')v=Math.max(9,Math.min(64,Number(v)||14));if(k==='height')v=Math.max(100,Math.min(500,Number(v)||200));b[k]=v;changed();updateBlockVisual(b);if(k==='height'||k==='size')el.value=v}
if(el.id==='photoUpload'){const b=selectedBlock(),file=el.files?.[0],mi=state.mission;if(!b||!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>1.5*1024*1024){notify('Choose a JPG, PNG or WebP photo smaller than 1.5 MB.');return}const r=new FileReader();r.onload=()=>{if(state.mission!==mi||!mission().blocks.some(x=>x.id===b.id))return;checkpoint();b.image='upload';b.upload=r.result;changed();updateBlockVisual(b);renderPanel();notify('Your photo is in the email. Add alt text to describe it.')};r.readAsDataURL(file)}});
document.addEventListener('paste',e=>{if(!e.target.matches('[data-content]'))return;e.preventDefault();const text=e.clipboardData.getData('text/plain');const selection=window.getSelection();if(!selection.rangeCount)return;const range=selection.getRangeAt(0);range.deleteContents();const node=document.createTextNode(text);range.insertNode(node);range.setStartAfter(node);range.collapse(true);selection.removeAllRanges();selection.addRange(range);e.target.dispatchEvent(new Event('input',{bubbles:true}))});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#modal').hidden)closeModal();if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!e.target.closest('[contenteditable],input,textarea')){e.preventDefault();undo(e.shiftKey)}});
let dragging=null;
document.addEventListener('dragstart',e=>{const h=e.target.closest('[data-drag]');if(!h||showOriginal||previewOnly)return;dragging=h.dataset.drag;e.dataTransfer.setData('text/plain',dragging);e.dataTransfer.effectAllowed='move'});
document.addEventListener('dragover',e=>{if(!dragging)return;const target=e.target.closest('[data-block]');if(target){e.preventDefault();$$('.dragover').forEach(x=>x.classList.remove('dragover'));target.classList.add('dragover')}});
document.addEventListener('drop',e=>{if(!dragging)return;const target=e.target.closest('[data-block]');e.preventDefault();$$('.dragover').forEach(x=>x.classList.remove('dragover'));if(target&&target.dataset.block!==dragging){const m=mission(),from=m.blocks.findIndex(x=>x.id===dragging),to=m.blocks.findIndex(x=>x.id===target.dataset.block);if(from>=0&&to>=0){checkpoint();const [b]=m.blocks.splice(from,1);m.blocks.splice(to,0,b);selected=b.id;changed();renderCanvas();renderPanel()}}dragging=null});
document.addEventListener('dragend',()=>{dragging=null;$$('.dragover').forEach(x=>x.classList.remove('dragover'))});
['pointerdown','keydown','scroll','touchstart'].forEach(name=>document.addEventListener(name,()=>{activity=Date.now();if(!state.started){state.started=true;persist()}},{passive:true}));
setInterval(()=>{const now=Date.now();if(state.started&&!state.complete&&!document.hidden&&now-activity<90000&&$('#modal').hidden)state.seconds+=Math.max(0,Math.min(2,Math.floor((now-lastTick)/1000)));lastTick=now;updateHeader();persist();if($('#gateText')){$('#gateText').textContent=gateText();$('#launchTime').textContent=displayTime();if($('#finishButton'))$('#finishButton').disabled=!canFinish()}},1000);
render();
